//! GM-646: the plugin binary flags every node of a generated file on the
//! wire (prost-build's `@generated` header), through the SDK's `extract_caught`, and leaves
//! every other node byte-identical. Drives the real binary's `--bulk-index`.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::{SystemTime, UNIX_EPOCH};

const BINARY: &str = env!("CARGO_BIN_EXE_g-mesh-plugin-rust");
const LANGUAGE: &str = "rust";
const GENERATED_PATH: &str = "src/foo.rs";
const GENERATED_SOURCE: &str = "// This file is @generated by prost-build.\npub struct Foo {\n    pub bar: i32,\n}\n\nimpl Foo {\n    pub fn get(&self) -> i32 {\n        self.bar\n    }\n}\n";
const PLAIN_PATH: &str = "src/lib.rs";
const PLAIN_SOURCE: &str = "// Plain header line.\npub struct Foo {\n    pub bar: i32,\n}\n\nimpl Foo {\n    pub fn get(&self) -> i32 {\n        self.bar\n    }\n}\n";

/// A scratch project directory that removes itself.
struct Scratch(PathBuf);

impl Scratch {
    fn new(files: &[(&str, &str)]) -> Self {
        let nanos = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or_default();
        let root =
            std::env::temp_dir().join(format!("g-mesh-gm646-{LANGUAGE}-{}-{nanos}", std::process::id()));
        for (path, contents) in files {
            let path = root.join(path);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, contents).unwrap();
        }
        Scratch(root)
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

/// The node lines (`qualifiedName` present) of a `--bulk-index` run, by file.
fn bulk_nodes_by_file(root: &Path) -> BTreeMap<String, Vec<serde_json::Value>> {
    let output = Command::new(BINARY).arg("--bulk-index").arg(root).output().expect("the plugin binary runs");
    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    let mut by_file: BTreeMap<String, Vec<serde_json::Value>> = BTreeMap::new();
    for line in String::from_utf8(output.stdout).unwrap().lines() {
        let value: serde_json::Value = serde_json::from_str(line).expect("every line is JSON");
        if value.get("qualifiedName").is_none() {
            continue;
        }
        let file = value["filePath"].as_str().expect("a node has a filePath").to_string();
        by_file.entry(file).or_default().push(value);
    }
    by_file
}

/// A bulk index of a project holding one file with a generated header and
/// one without: every node of the first carries `"generated":true`, and no
/// node of the second carries the key at all (byte-identical to before).
///
/// Control: drop the `is_generated` branch in `run::extract_caught`
/// (plugins/sdk/src/run.rs); every node of the generated file loses the flag.
#[test]
fn a_bulk_index_flags_every_node_of_a_generated_file_and_no_other() {
    let scratch = Scratch::new(&[(GENERATED_PATH, GENERATED_SOURCE), (PLAIN_PATH, PLAIN_SOURCE)]);
    let by_file = bulk_nodes_by_file(&scratch.0);

    let generated =
        by_file.get(GENERATED_PATH).unwrap_or_else(|| panic!("no nodes for {GENERATED_PATH}: {by_file:?}"));
    assert!(generated.len() >= 2, "the File node plus declarations: {generated:?}");
    for node in generated {
        assert_eq!(node.get("generated"), Some(&serde_json::Value::Bool(true)), "{node}");
    }
    let plain = by_file.get(PLAIN_PATH).unwrap_or_else(|| panic!("no nodes for {PLAIN_PATH}: {by_file:?}"));
    assert!(plain.len() >= 2, "the File node plus declarations: {plain:?}");
    for node in plain {
        assert!(node.get("generated").is_none(), "an ordinary node carries no generated key: {node}");
    }
}

/// One `fileChanged` round trip over the plugin's control-plane wire
/// (`Content-Length` framing), the way `workspace_changed.rs` drives it.
struct Client {
    child: std::process::Child,
    stdin: std::process::ChildStdin,
    stdout: std::io::BufReader<std::process::ChildStdout>,
    next_id: u64,
}

impl Client {
    fn spawn(root: &Path) -> Self {
        use std::process::Stdio;
        let mut child = Command::new(BINARY)
            .arg(root)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()
            .expect("failed to spawn the plugin");
        let stdin = child.stdin.take().expect("piped stdin");
        let stdout = std::io::BufReader::new(child.stdout.take().expect("piped stdout"));
        let mut client = Self { child, stdin, stdout, next_id: 1 };
        let handshake = client.read_message();
        assert_eq!(handshake["language"], LANGUAGE, "{handshake}");
        client
    }

    fn read_message(&mut self) -> serde_json::Value {
        use std::io::{BufRead, Read};
        let mut length = None;
        loop {
            let mut line = String::new();
            self.stdout.read_line(&mut line).expect("the plugin closed its stdout mid-frame");
            let line = line.trim_end_matches(['\n', '\r']);
            if line.is_empty() {
                break;
            }
            if let Some((name, value)) = line.split_once(':') {
                if name.trim().eq_ignore_ascii_case("Content-Length") {
                    length = Some(value.trim().parse::<usize>().expect("a numeric Content-Length"));
                }
            }
        }
        let mut body = vec![0u8; length.expect("a frame header without Content-Length")];
        self.stdout.read_exact(&mut body).expect("a full frame body");
        serde_json::from_slice(&body).expect("a JSON frame body")
    }

    fn file_changed(&mut self, path: &str) -> Vec<serde_json::Value> {
        use std::io::Write;
        let id = self.next_id;
        self.next_id += 1;
        let body = serde_json::to_vec(&serde_json::json!({
            "jsonrpc": "2.0", "id": id, "method": "fileChanged", "params": { "filePath": path }
        }))
        .unwrap();
        write!(self.stdin, "Content-Length: {}\r\n\r\n", body.len()).unwrap();
        self.stdin.write_all(&body).unwrap();
        self.stdin.flush().unwrap();
        let response = self.read_message();
        response["result"]["upsertNodes"]
            .as_array()
            .unwrap_or_else(|| panic!("no upsertNodes in the answer for {path}: {response}"))
            .clone()
    }

    fn shutdown(mut self) {
        drop(self.stdin);
        let _ = self.child.wait();
    }
}

/// `fileChanged`: putting a generated header on an indexed file (same line
/// count, so only the header text differs) re-sends its nodes with the flag
/// set, and taking it off re-sends them without the key.
///
/// Control: drop the `is_generated` branch in `run::extract_caught`; the
/// "marker added" answer carries no flag.
#[test]
fn file_changed_flips_the_generated_flag_when_the_header_comes_and_goes() {
    let scratch = Scratch::new(&[(PLAIN_PATH, PLAIN_SOURCE)]);
    let mut client = Client::spawn(&scratch.0);
    let marked =
        PLAIN_SOURCE.replacen("// Plain header line.", "// This file is @generated by prost-build.", 1);
    let named = |nodes: &[serde_json::Value], name: &str| nodes.iter().any(|node| node["name"] == name);

    let first = client.file_changed(PLAIN_PATH);
    assert!(first.iter().all(|node| node.get("generated").is_none()), "{first:?}");

    std::fs::write(scratch.0.join(PLAIN_PATH), &marked).unwrap();
    let added = client.file_changed(PLAIN_PATH);
    assert!(named(&added, "Foo"), "the declarations are re-sent once the header appears: {added:?}");
    for node in &added {
        assert_eq!(node.get("generated"), Some(&serde_json::Value::Bool(true)), "{node}");
    }

    std::fs::write(scratch.0.join(PLAIN_PATH), PLAIN_SOURCE).unwrap();
    let removed = client.file_changed(PLAIN_PATH);
    assert!(named(&removed, "Foo"), "the declarations are re-sent once the header goes: {removed:?}");
    assert!(removed.iter().all(|node| node.get("generated").is_none()), "{removed:?}");

    client.shutdown();
}
